// Extract textual content from raw HTML (fallback to empty if failed)
const webhookBody = $('Webhook (New Lead)').item.json.body;
const html = typeof $json.data === 'string' ? $json.data : ($json.body || '');
const stripTags = (s) => s.replace(/<script[\s\S]*?<\/script>/gi, ' ').replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
const titleMatch = html.match(/<title>([^<]*)<\/title>/i);
const descMatch = html.match(/<meta[^>]*name=["']description["'][^>]*content=["']([^"']*)["']/i);
const bodyText = stripTags(html).slice(0, 3000);
return {
  lead: webhookBody,
  site: {
    title: titleMatch ? titleMatch[1].trim() : '',
    description: descMatch ? descMatch[1].trim() : '',
    bodyText,
  }
};

